1	// ─── PPP (Purchasing Power Parity) Config ───
2	// Hardcoded tier definitions and country-to-tier mappings.
3	// Tiers determine the discount percentage applied at purchase time.
4	
5	export const PPP_TIERS = {
6	  1: { discount: 0, label: "Full Price" },
7	  2: { discount: 0.3, label: "30% off" },
8	  3: { discount: 0.5, label: "50% off" },
9	  4: { discount: 0.7, label: "70% off" },
10	} as const;
11	
12	export type PppTier = keyof typeof PPP_TIERS;
13	
14	const COUNTRY_TIER_MAP: Record<string, PppTier> = {
15	  // Tier 1 — Full price
16	  US: 1, CA: 1, GB: 1, AU: 1, DE: 1, FR: 1, NL: 1, SE: 1, NO: 1, CH: 1, JP: 1, SG: 1,
17	  // Tier 2 — 30% off
18	  PL: 2, MX: 2, BR: 2, TR: 2, TH: 2, MY: 2, CZ: 2, CL: 2,
19	  // Tier 3 — 50% off
20	  IN: 3, CO: 3, AR: 3, ZA: 3, PH: 3, VN: 3, UA: 3, ID: 3,
21	  // Tier 4 — 70% off
22	  NG: 4, PK: 4, BD: 4, EG: 4, KE: 4, ET: 4,
23	};
24	
25	export function getTierForCountry(countryCode: string | null): PppTier {
26	  if (!countryCode) return 1;
27	  return COUNTRY_TIER_MAP[countryCode.toUpperCase()] ?? 1;
28	}
29	
30	export function getDiscountForCountry(countryCode: string | null): number {
31	  const tier = getTierForCountry(countryCode);
32	  return PPP_TIERS[tier].discount;
33	}
34	
35	export function calculatePppPrice(priceInCents: number, countryCode: string | null): number {
36	  const discount = getDiscountForCountry(countryCode);
37	  return Math.round(priceInCents * (1 - discount));
38	}
39	
40	export function getCountryTierInfo(countryCode: string | null) {
41	  const tier = getTierForCountry(countryCode);
42	  const { discount, label } = PPP_TIERS[tier];
43	  return { tier, discount, label };
44	}
45	
46	/**
47	 * Pure function to check if PPP access should be blocked.
48	 * Returns blocked=true when a discounted purchase is accessed from a different country.
49	 */
50	export function checkPppAccess(
51	  coursePrice: number,
52	  coursePppEnabled: boolean,
53	  purchaseCountry: string | null,
54	  currentCountry: string | null
55	): { blocked: boolean; blockedCountry: string | null; purchaseCountry: string | null } {
56	  const result = { blocked: false, blockedCountry: null as string | null, purchaseCountry: null as string | null };
57	
58	  // Skip: free courses or PPP-disabled courses
59	  if (coursePrice <= 0 || !coursePppEnabled) return result;
60	
61	  // Skip: no purchase country recorded
62	  if (!purchaseCountry) return result;
63	
64	  // Skip: full-price (Tier 1) purchases — no geographic restriction
65	  const purchaseTier = getTierForCountry(purchaseCountry);
66	  if (purchaseTier === 1) return result;
67	
68	  // Discounted purchase — verify country match
69	  if (currentCountry && currentCountry !== purchaseCountry) {
70	    result.blocked = true;
71	    result.blockedCountry = currentCountry;
72	    result.purchaseCountry = purchaseCountry;
73	  }
74	
75	  return result;
76	}
