22	export async function loader({ request }: Route.LoaderArgs) {
23	  const currentUserId = await getCurrentUserId(request);
24	
25	  if (!currentUserId) {
26	    throw data("Select a user from the DevUI panel to view your courses.", {
27	      status: 401,
28	    });
29	  }
30	
31	  const user = getUserById(currentUserId);
32	
33	  if (!user || user.role !== UserRole.Instructor) {
34	    throw data("Only instructors can access this page.", {
35	      status: 403,
36	    });
37	  }
38	
39	  const instructorCourses = getCoursesByInstructor(currentUserId);
40	
41	  const coursesWithStats = instructorCourses.map((course) => {
42	    const lessonCount = getLessonCountForCourse(course.id);
43	    const enrollmentCount = getEnrollmentCountForCourse(course.id);
44	
45	    return {
46	      id: course.id,
47	      title: course.title,
48	      slug: course.slug,
49	      description: course.description,
50	      status: course.status,
51	      coverImageUrl: course.coverImageUrl,
52	      lessonCount,
53	      enrollmentCount,
54	      createdAt: course.createdAt,
55	      updatedAt: course.updatedAt,
56	    };
57	  });
58	
59	  return { courses: coursesWithStats };
60	}
