225	export function ErrorBoundary({ error }: Route.ErrorBoundaryProps) {
226	  let title = "Something went wrong";
227	  let message = "An unexpected error occurred while loading your courses.";
228	
229	  if (isRouteErrorResponse(error)) {
230	    if (error.status === 401) {
231	      title = "Sign in required";
232	      message = typeof error.data === "string" ? error.data : "Please select a user from the DevUI panel.";
233	    } else if (error.status === 403) {
234	      title = "Access denied";
235	      message = typeof error.data === "string" ? error.data : "You don't have permission to access this page.";
236	    } else {
237	      title = `Error ${error.status}`;
238	      message = typeof error.data === "string" ? error.data : error.statusText;
239	    }
240	  }
241	
242	  return (
243	    <div className="flex min-h-[50vh] items-center justify-center p-6">
244	      <div className="text-center">
245	        <AlertTriangle className="mx-auto mb-4 size-12 text-muted-foreground" />
246	        <h1 className="mb-2 text-2xl font-bold">{title}</h1>
247	        <p className="mb-6 text-muted-foreground">{message}</p>
248	        <div className="flex items-center justify-center gap-3">
249	          <Link to="/courses">
250	            <Button variant="outline">Browse Courses</Button>
251	          </Link>
252	          <Link to="/">
253	            <Button>Go Home</Button>
254	          </Link>
255	        </div>
256	      </div>
257	    </div>
258	  );
259	}
