41	export async function loader({ request }: Route.LoaderArgs) {
42	  const currentUserId = await getCurrentUserId(request);
43	
44	  if (!currentUserId) {
45	    throw data("Select a user from the DevUI panel to create a course.", {
46	      status: 401,
47	    });
48	  }
49	
50	  const user = getUserById(currentUserId);
51	
52	  if (!user || user.role !== UserRole.Instructor) {
53	    throw data("Only instructors can create courses.", {
54	      status: 403,
55	    });
56	  }
57	
58	  const categories = getAllCategories();
