63	export async function action({ request }: Route.ActionArgs) {
64	  const currentUserId = await getCurrentUserId(request);
65	
66	  if (!currentUserId) {
67	    throw data("You must be logged in to create a course.", { status: 401 });
68	  }
69	
70	  const user = getUserById(currentUserId);
71	
72	  if (!user || user.role !== UserRole.Instructor) {
73	    throw data("Only instructors can create courses.", { status: 403 });
74	  }
75	
76	  const formData = await request.formData();
77	  const parsed = parseFormData(formData, newCourseSchema);
78	
79	  if (!parsed.success) {
80	    return data({ errors: parsed.errors }, { status: 400 });
81	  }
82	
83	  const { title, description, categoryId, coverImageUrl } = parsed.data;
84	
85	  const slug = generateSlug(title);
86	
87	  const existingCourse = getCourseBySlug(slug);
88	  if (existingCourse) {
89	    return data(
90	      { errors: { title: "A course with a similar title already exists." } as Record<string, string> },
91	      { status: 400 }
92	    );
93	  }
94	
95	  const course = createCourse(
96	    title,
97	    slug,
98	    description,
99	    currentUserId,
100	    parseInt(categoryId, 10),
101	    coverImageUrl || null
102	  );
103	
104	  throw redirect(`/courses/${course.slug}`);
105	}
