42	
43	  const courseId = parseInt(params.courseId, 10);
44	  if (isNaN(courseId)) {
45	    throw data("Invalid course ID.", { status: 400 });
46	  }
47	
48	  const course = getCourseById(courseId);
49	
50	  if (!course) {
51	    throw data("Course not found.", { status: 404 });
52	  }
53	
54	  if (course.instructorId !== currentUserId && user.role !== UserRole.Admin) {
55	    throw data("You can only view students for your own courses.", {
56	      status: 403,
57	    });
58	  }
59	
60	  // Get all enrolled students
61	  const enrolledStudents = getCourseEnrolledStudents(courseId);
