66	    .from(modules)
67	    .where(eq(modules.courseId, courseId))
68	    .all();
69	
70	  // Get all lessons across all modules
71	  const allCourseLessons: { id: number; title: string }[] = [];
72	  for (const mod of courseModules) {
73	    const modLessons = db
74	      .select({ id: lessons.id, title: lessons.title })
75	      .from(lessons)
76	      .where(eq(lessons.moduleId, mod.id))
77	      .all();
78	    allCourseLessons.push(...modLessons);
79	  }
80	
81	  // Find which lessons have quizzes
82	  const lessonQuizzes: { lessonId: number; lessonTitle: string; quizId: number; quizTitle: string }[] = [];
83	  for (const lesson of allCourseLessons) {
84	    const quiz = getQuizByLessonId(lesson.id);
85	    if (quiz) {
86	      lessonQuizzes.push({
87	        lessonId: lesson.id,
88	        lessonTitle: lesson.title,
