6	// ─── Coupon Service ───
7	// Handles coupon generation, redemption (with validation), and listing.
8	// Each coupon grants one seat for a specific course within a team.
9	
10	function generateCode(): string {
11	  return crypto.randomBytes(12).toString("base64url");
12	}
13	
14	export function generateCoupons(
15	  teamId: number,
16	  courseId: number,
17	  purchaseId: number,
18	  quantity: number
19	) {
20	  const created: (typeof coupons.$inferSelect)[] = [];
21	  for (let i = 0; i < quantity; i++) {
22	    const coupon = db
23	      .insert(coupons)
24	      .values({
25	        teamId,
26	        courseId,
27	        code: generateCode(),
28	        purchaseId,
29	      })
30	      .returning()
31	      .get();
32	    created.push(coupon);
33	  }
34	  return created;
35	}
36	
37	export function getCouponByCode(code: string) {
38	  return db.select().from(coupons).where(eq(coupons.code, code)).get();
39	}
40	
41	export function getCouponsForTeam(teamId: number, courseId?: number) {
42	  if (courseId !== undefined) {
43	    return db
44	      .select()
45	      .from(coupons)
46	      .where(and(eq(coupons.teamId, teamId), eq(coupons.courseId, courseId)))
47	      .all();
48	  }
49	  return db.select().from(coupons).where(eq(coupons.teamId, teamId)).all();
50	}
51	
52	export type RedeemResult =
53	  | { ok: true; enrollment: typeof enrollments.$inferSelect }
54	  | { ok: false; error: string };
55	
56	export function redeemCoupon(
57	  code: string,
58	  userId: number,
59	  userCountry: string
60	): RedeemResult {
61	  // 1. Find the coupon
62	  const coupon = getCouponByCode(code);
63	  if (!coupon) {
64	    return { ok: false, error: "Coupon not found" };
65	  }
66	
67	  // 2. Check if already consumed
68	  if (coupon.redeemedByUserId !== null) {
69	    return { ok: false, error: "Coupon has already been redeemed" };
70	  }
71	
72	  // 3. Check if user is already enrolled
73	  const existingEnrollment = db
74	    .select()
75	    .from(enrollments)
76	    .where(
77	      and(
78	        eq(enrollments.userId, userId),
79	        eq(enrollments.courseId, coupon.courseId)
80	      )
81	    )
82	    .get();
83	
84	  if (existingEnrollment) {
85	    return { ok: false, error: "You are already enrolled in this course" };
86	  }
87	
88	  // 4. Country check: match purchaser's country
89	  const purchase = db
90	    .select()
91	    .from(purchases)
92	    .where(eq(purchases.id, coupon.purchaseId))
93	    .get();
94	
95	  if (purchase?.country && purchase.country !== userCountry) {
96	    return {
97	      ok: false,
98	      error:
99	        "This coupon can only be redeemed from the same country as the purchaser",
100	    };
101	  }
102	
103	  // 5. Redeem: mark coupon consumed + enroll user
104	  db.update(coupons)
105	    .set({
106	      redeemedByUserId: userId,
107	      redeemedAt: new Date().toISOString(),
108	    })
109	    .where(eq(coupons.id, coupon.id))
110	    .run();
111	
112	  const enrollment = db
113	    .insert(enrollments)
114	    .values({ userId, courseId: coupon.courseId })
115	    .returning()
116	    .get();
117	
118	  return { ok: true, enrollment };
119	}
